// Indexed by cambc::champion_type value. An unknown type (a champion added in a patch before
// this table is regenerated) gets an empty design instead of reading past the table.
inline const ChampionDesign& design_for(int type) {
    static const ChampionDesign unknown{};
    return type >= 0 && type < kChampionTypeCount ? kDesigns[type] : unknown;
}
